// ---------- replies ----------

func writeSimple(w *bufio.Writer, s string) {
	w.WriteString("+")
	w.WriteString(s)
	w.WriteString("\r\n")
}

func writeError(w *bufio.Writer, msg string) {
	// addReplyError prefixes "-ERR " unless the caller already supplied a code.
	w.WriteString("-ERR ")
	w.Write(sanitize([]byte(msg)))
	w.WriteString("\r\n")
}

func writeInt(w *bufio.Writer, n int64) {
	w.WriteByte(':')
	w.WriteString(strconv.FormatInt(n, 10))
	w.WriteString("\r\n")
}

func writeBulk(w *bufio.Writer, b []byte) {
	w.WriteByte('$')
	w.WriteString(strconv.Itoa(len(b)))
	w.WriteString("\r\n")
	w.Write(b)
	w.WriteString("\r\n")
}

func writeNullBulk(w *bufio.Writer) {
	w.WriteString("$-1\r\n")
}

// ---------- RESP reader ----------

func readCommand(r *bufio.Reader) ([][]byte, error) {
	b, err := r.ReadByte()
	if err != nil {
		return nil, err
	}
	if b == '*' {
		return readMultibulk(r)
	}
	if err := r.UnreadByte(); err != nil {
		return nil, err
	}
	return readInline(r)
}

func readMultibulk(r *bufio.Reader) ([][]byte, error) {
	line, err := readCRLFLine(r, protoInlineMaxSize, "Protocol error: too big mbulk count string")
	if err != nil {
		return nil, err
